import{_ as n,y as o,a,o as i,a2 as t,D as r}from"./chunks/framework.DCcmcJcL.js";const m=JSON.parse('{"title":"Search Engines","description":"","frontmatter":{},"headers":[],"relativePath":"configure/search-engines.md","filePath":"configure/search-engines.md","lastUpdated":1789441803000}'),h={name:"configure/search-engines.md"};function g(d,e,c,l,u,p){const s=o("ImagePopup");return i(),a("div",null,[e[0]||(e[0]=t('<h1 id="search-engines" tabindex="-1">Search Engines <a class="header-anchor" href="#search-engines" aria-label="Permalink to &quot;Search Engines&quot;">​</a></h1><p>Product search on the storefront and in the admin panel runs on the database by default. For a large catalog, you can connect an Elasticsearch cluster and choose where it is used. The <strong>Search Engines</strong> group has two screens, <strong>General</strong> and <strong>Elasticsearch</strong>, and every setting on them applies to the whole store.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Search Engines &gt;&gt; General</strong>.</li><li>In <strong>Settings</strong>, switch <strong>Enable External Search Engine</strong> on. <strong>Default Search Engine</strong> appears.</li><li>Choose the <strong>Default Search Engine</strong>: <strong>Database</strong> (the default) or <strong>Elasticsearch</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p><strong>Enable External Search Engine:</strong> While it is off, every search runs on the database, whatever the other settings say. It is off by default.</p><p><strong>Default Search Engine:</strong> The engine used wherever a search mode below is left on <strong>Use Default</strong>. If it is <strong>Database</strong>, every search uses the database, whatever the search modes say.</p><h2 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Search Engines &gt;&gt; General</strong>.</li><li>In <strong>Products</strong>, choose the <strong>Admin Search Mode</strong>.</li><li>Choose the <strong>Storefront Search Mode</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',8)),r(s,{src:"/images/configure/search-engines-general.png",alt:"General screen of the Search Engines group with the external search engine turned on and Elasticsearch as the default"}),e[1]||(e[1]=t('<p><strong>Admin Search Mode:</strong> The engine behind product search in the admin panel: the product results of the header search, the product grid and the product pickers.</p><p><strong>Storefront Search Mode:</strong> The engine behind category pages, the search page and the other searches on the storefront.</p><p>Each search mode can be <strong>Use Default</strong> (the default), <strong>Database</strong> or <strong>Elasticsearch</strong>. A mode only uses Elasticsearch while <strong>Default Search Engine</strong> is <strong>Elasticsearch</strong>. For example, to keep the admin panel on the database while the storefront uses Elasticsearch, set <strong>Default Search Engine</strong> to <strong>Elasticsearch</strong> and <strong>Admin Search Mode</strong> to <strong>Database</strong>.</p><h2 id="elasticsearch" tabindex="-1">Elasticsearch <a class="header-anchor" href="#elasticsearch" aria-label="Permalink to &quot;Elasticsearch&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Search Engines &gt;&gt; Elasticsearch</strong>.</li><li>In <strong>Settings</strong>, choose the <strong>Authentication</strong>. Only the fields that method needs are shown.</li><li>Enter the connection details described in the table.</li><li>Click <strong>Test Connection</strong> to check the details on screen. You don&#39;t have to save them first.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',5)),r(s,{src:"/images/configure/search-engines-elasticsearch.png",alt:"Elasticsearch screen with username and password authentication and the Test Connection button"}),e[2]||(e[2]=t('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Authentication</strong></td><td>How the store signs in to the cluster: <strong>No authentication</strong> (the default), <strong>Username and password</strong>, <strong>API key</strong>, <strong>Elastic Cloud with API key</strong> or <strong>Elastic Cloud with username and password</strong>.</td></tr><tr><td><strong>Hosts</strong></td><td>Appears for <strong>No authentication</strong>, <strong>Username and password</strong> and <strong>API key</strong>. Where the cluster is reached, such as <code>http://localhost:9200</code>. Separate several hosts with a comma. Leave it empty to use the value from the server&#39;s environment file.</td></tr><tr><td><strong>Cloud ID</strong></td><td>Appears for the two <strong>Elastic Cloud</strong> methods. The Cloud ID of your Elastic Cloud deployment.</td></tr><tr><td><strong>Username</strong></td><td>Appears for the two username and password methods.</td></tr><tr><td><strong>Password</strong></td><td>Appears with <strong>Username</strong>. The password paired with it.</td></tr><tr><td><strong>API Key</strong></td><td>Appears for the two API key methods.</td></tr><tr><td><strong>Index Prefix</strong></td><td>Added to the front of every index name, so several stores can share one cluster.</td></tr><tr><td><strong>Minimum Query Length</strong></td><td>The shortest search term the storefront search box accepts. The default is <code>0</code>.</td></tr><tr><td><strong>Maximum Query Length</strong></td><td>The longest search term the storefront search box accepts. The default is <code>1000</code>.</td></tr></tbody></table><p>The two query lengths apply to the storefront search box whichever engine it uses.</p><p>The result of <strong>Test Connection</strong> appears next to the button:</p><ul><li><strong>Elasticsearch is available</strong></li><li><strong>Elasticsearch did not answer</strong></li><li><strong>Elasticsearch rejected the credentials</strong></li><li><strong>The host answered but is not a supported Elasticsearch server</strong></li><li><strong>The Elasticsearch connection is not configured</strong></li></ul><p>Below the result, the host that was tested is shown. When the cluster answers, its version and cluster name follow.</p><h3 id="build-the-index" tabindex="-1">Build the index <a class="header-anchor" href="#build-the-index" aria-label="Permalink to &quot;Build the index&quot;">​</a></h3><p>A cluster only returns products that have been indexed. Products are indexed only while <strong>Enable External Search Engine</strong> is on and <strong>Default Search Engine</strong> is <strong>Elasticsearch</strong>. After connecting a cluster for the first time, ask whoever manages the server to run the product indexer. From then on, a product is indexed again whenever it is created, updated or deleted. If your server runs background jobs through a queue, the queue has to be running for these updates. See <a href="./../getting-started/scheduled-tasks.html">Scheduled Tasks</a>.</p><h2 id="differences-in-bagisto-2-4" tabindex="-1">Differences in Bagisto 2.4 <a class="header-anchor" href="#differences-in-bagisto-2-4" aria-label="Permalink to &quot;Differences in Bagisto 2.4&quot;">​</a></h2><p>Bagisto 2.4 has no <strong>Search Engines</strong> group. Its <strong>Search Engine</strong>, <strong>Admin Search Mode</strong> and <strong>Storefront Search Mode</strong> settings, and its <strong>Minimum query length</strong> and <strong>Maximum query length</strong>, are in the <strong>Search</strong> section under <strong>Configure &gt;&gt; Catalog &gt;&gt; Products</strong>. The engines to choose from there are <strong>Database</strong> and <strong>Elastic Search</strong>, and the Elasticsearch connection is set in the server&#39;s environment file.</p>',9))])}const E=n(h,[["render",g]]);export{m as __pageData,E as default};
